import { useVirtualizer } from '@tanstack/react-virtual'
import { useRef } from 'react'

export function Grid() {
  const ref = useRef<HTMLDivElement>(null)
  const rows = useVirtualizer({ count: 10000, getScrollElement: () => ref.current, estimateSize: () => 35 })
  const columns = useVirtualizer({ horizontal: true, count: 200, getScrollElement: () => ref.current, estimateSize: () => 100 })
  return <div ref={ref} style={{ height: 500, width: 500, overflow: 'auto', position: 'relative' }}><div style={{ height: rows.getTotalSize(), width: columns.getTotalSize(), position: 'relative' }}>{rows.getVirtualItems().flatMap(row => columns.getVirtualItems().map(col => <div key={`${row.key}-${col.key}`} style={{ position: 'absolute', top: 0, left: 0, width: col.size, height: row.size, transform: `translateX(${col.start}px) translateY(${row.start}px)` }}>Cell {row.index}, {col.index}</div>))}</div></div>
}

