import { useMemo, useRef } from 'react'
import { useVirtualizer } from '@tanstack/react-virtual'

const groups = ['A', 'B', 'C']
const rows = groups.flatMap(group => [group, ...Array.from({ length: 4 }, (_, i) => `${group}${i + 1}`)])
const stickyIndexes = useMemo(() => groups.map(group => rows.indexOf(group)), [])
const activeStickyIndexRef = useRef(stickyIndexes[0])
const isSticky = (index: number) => stickyIndexes.includes(index)
const isActiveSticky = (index: number) => activeStickyIndexRef.current === index

export function StickyList() {
  const parentRef = useRef<HTMLDivElement>(null)
  const virtualizer = useVirtualizer({
    count: rows.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => 36,
    rangeExtractor: range => {
      const active = [...stickyIndexes].reverse().find(index => index <= range.startIndex)
      activeStickyIndexRef.current = active ?? stickyIndexes[0]
      return Array.from(new Set([activeStickyIndexRef.current, ...virtualizer.getVirtualIndexes()])).sort((a, b) => a - b)
    },
  })

  return <div ref={parentRef} style={{ height: 240, overflow: 'auto' }}><div style={{ height: virtualizer.getTotalSize(), position: 'relative' }}>{virtualizer.getVirtualItems().map(item => <div key={item.index} style={{ ...(isActiveSticky(item.index) ? { position: 'sticky' } : { position: 'absolute', transform: `translateY(${item.start}px)` }), top: 0, left: 0, width: '100%', height: item.size, background: '#fff', zIndex: 1 }}>{rows[item.index]}</div>)}</div></div>
}

