import * as React from 'react'
import { useVirtualizer } from '@tanstack/react-virtual'
import { useInfiniteQuery } from '@tanstack/react-query'

async function fetchServerPage(limit: number, offset = 0) {
  const rows = Array.from({ length: limit }, (_, i) => `Row ${i + offset * limit}`)
  return { rows, nextOffset: offset + 1 }
}

export default function App() {
  const query = useInfiniteQuery({
    queryKey: ['rows'],
    queryFn: ({ pageParam }) => fetchServerPage(20, pageParam),
    getNextPageParam: lastPage => lastPage.nextOffset,
    initialPageParam: 0,
  })
  const rows = query.data?.pages.flatMap(page => page.rows) ?? []
  const parentRef = React.useRef<HTMLDivElement>(null)
  const virtualizer = useVirtualizer({
    count: query.hasNextPage ? rows.length + 1 : rows.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => 35,
  })
  React.useEffect(() => {
    const last = virtualizer.getVirtualItems().at(-1)
    if (last && last.index >= rows.length - 1 && query.hasNextPage && !query.isFetchingNextPage) query.fetchNextPage()
  }, [virtualizer.getVirtualItems(), rows.length, query.hasNextPage, query.isFetchingNextPage])
  return <div ref={parentRef} style={{ height: 400, overflow: 'auto' }}><div style={{ height: virtualizer.getTotalSize(), position: 'relative' }}>{virtualizer.getVirtualItems().map(item => <div key={item.key} style={{ position: 'absolute', transform: `translateY(${item.start}px)` }}>{rows[item.index] ?? 'Loading...'}</div>)}</div></div>
}

