import { Virtualizer } from '@tanstack/virtual-core'

const scrollElement = document.querySelector('#list')!
const virtualizer = new Virtualizer({
  count: 1000,
  getScrollElement: () => scrollElement,
  estimateSize: () => 40,
  observeElementRect: (instance, cb) => {
    const observer = new ResizeObserver(() => cb({ width: scrollElement.clientWidth, height: scrollElement.clientHeight }))
    observer.observe(scrollElement)
    return () => observer.disconnect()
  },
  observeElementOffset: (instance, cb) => {
    const onScroll = () => cb(scrollElement.scrollTop)
    scrollElement.addEventListener('scroll', onScroll)
    return () => scrollElement.removeEventListener('scroll', onScroll)
  },
  scrollToFn: (offset, options) => scrollElement.scrollTo({ top: offset, behavior: options.behavior }),
})

virtualizer.scrollToIndex(180, { align: 'center', behavior: 'smooth' })

